import{_ as o,o as s,c as i,a3 as n}from"./chunks/framework.BwtvuMfj.js";const g=JSON.parse('{"title":"常见问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),t={name:"guide/faq.md"};function a(d,e,c,r,l,p){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="常见问题排查" tabindex="-1">常见问题排查 <a class="header-anchor" href="#常见问题排查" aria-label="Permalink to &quot;常见问题排查&quot;">​</a></h1><p>接入 <code>encode-fe-lint</code> 后遇到的典型问题与处理方式。</p><hr><h2 id="_1-扫描结果里全是-parsing-error" tabindex="-1">1. 扫描结果里全是 <code>Parsing error</code> <a class="header-anchor" href="#_1-扫描结果里全是-parsing-error" aria-label="Permalink to &quot;1. 扫描结果里全是 `Parsing error`&quot;">​</a></h2><p><strong>现象</strong>：<code>scan</code> 输出大量 <code>Parsing error: The keyword &#39;import&#39; is reserved</code>、<code>Unexpected token &lt;</code>、<code>Unexpected token module</code> 等报错，几乎覆盖所有 <code>.ts</code> / <code>.vue</code> / <code>.d.ts</code> 文件。</p><p><strong>原因</strong>：项目中使用的是 Flat Config（<code>eslint.config.*</code>），但 ESLint 没有加载它，导致退回默认的 espree 解析器（ES5 + script 模式），所有 ESM / TS / Vue 语法都无法解析。</p><p><strong>处理</strong>：</p><ol><li>将 <code>@huangjunsen/eslint-config</code> 升级到 <code>&gt;=1.0.3</code>，其中包含可用的 Flat Config 预设；</li><li>将 <code>@huangjunsen/encode-fe-lint</code> 升级到 <code>&gt;=1.0.12</code>，该版本会在检测到 <code>eslint.config.*</code> 时自动启用 FlatESLint；</li><li>确认 <code>eslint.config.mjs</code> 的入口与项目类型匹配（见 <a href="/js-encode-fe-spec/packages/eslint-config.html">ESLint 规则配置</a>）。</li></ol><blockquote><p>自 <code>1.0.12</code> 起，CLI 会优先探测项目根目录的 <code>eslint.config.js/mjs/cjs/ts</code>，存在时交由 ESLint 自行加载扁平配置，否则继续使用传统的 <code>.eslintrc.*</code> 初始化逻辑。</p></blockquote><hr><h2 id="_2-fix-时报-cannot-find-module-xxx-prettier-config-并中断" tabindex="-1">2. <code>fix</code> 时报 <code>Cannot find module &#39;xxx/prettier-config&#39;</code> 并中断 <a class="header-anchor" href="#_2-fix-时报-cannot-find-module-xxx-prettier-config-并中断" aria-label="Permalink to &quot;2. `fix` 时报 `Cannot find module &#39;xxx/prettier-config&#39;` 并中断&quot;">​</a></h2><p><strong>现象</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>Error: Cannot find module &#39;@sxzz/prettier-config&#39;</span></span>\n<span class="line"><span>    at Object.transform (.../prettier/index.js)</span></span></code></pre></div><p><strong>原因</strong>：早期版本在生成待处理文件列表时使用了绝对路径，导致 <code>fast-glob</code> 的 <code>ignore</code> 规则失效，把 <code>node_modules</code> 中第三方依赖的 <code>README.md</code> / 配置一并纳入格式化范围。这些依赖的 <code>package.json</code> 里可能声明了未安装的 <code>prettier</code> 配置包，从而触发模块解析失败并中断整个进程。</p><p><strong>处理</strong>：升级 <code>@huangjunsen/encode-fe-lint</code> 到 <code>&gt;=1.0.12</code>。</p><p>该版本做了三处修复：</p><ul><li>待扫描路径统一归一化为「相对 cwd」，保证 ignore 规则正常生效；</li><li><code>node_modules</code> 忽略规则调整为 <code>**/node_modules/**</code>，覆盖 monorepo 中的嵌套依赖目录；</li><li>单个文件的格式化失败不再中断整体流程，而是作为异常统一上报。</li></ul><hr><h2 id="_3-样式文件报-unknown-rule-xxx" tabindex="-1">3. 样式文件报 <code>Unknown rule xxx</code> <a class="header-anchor" href="#_3-样式文件报-unknown-rule-xxx" aria-label="Permalink to &quot;3. 样式文件报 `Unknown rule xxx`&quot;">​</a></h2><p><strong>现象</strong>：stylelint 输出 <code>Unknown rule selector-anb-no-unmatchable</code> 之类的错误。</p><p><strong>原因</strong>：<code>encode-fe-lint</code> 内置的 stylelint 版本低于 <code>@huangjunsen/stylelint-config</code> 所引用的 <code>stylelint-config-standard</code>。</p><p><strong>处理</strong>：升级 <code>@huangjunsen/encode-fe-lint</code> 到 <code>&gt;=1.0.13</code>（内置 stylelint 15）。</p><hr><h2 id="_4-格式化后出现-parsing-error-unexpected-token-did-you-mean" tabindex="-1">4. 格式化后出现 <code>Parsing error: Unexpected token. Did you mean {&#39;&#39;&gt;&#39;&#39;}</code> <a class="header-anchor" href="#_4-格式化后出现-parsing-error-unexpected-token-did-you-mean" aria-label="Permalink to &quot;4. 格式化后出现 `Parsing error: Unexpected token. Did you mean {&#39;&#39;&gt;&#39;&#39;}`&quot;">​</a></h2><p><strong>现象</strong>：<code>.vue</code> 文件中使用了泛型写法，<code>fix</code> 之后扫描突然报解析错误，位置指向箭头函数的 <code>=&gt;</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>91:25  error  Parsing error: Unexpected token. Did you mean `{&#39;&gt;&#39;}` or `&amp;gt;`?</span></span></code></pre></div><p><strong>原因</strong>：Vue 单文件组件中，泛型箭头函数必须写成 <code>&lt;T,&gt;(...)</code> 这种带尾逗号的形式，用于和 JSX 标签区分。</p><p>早期版本内置 Prettier 2.x，它在处理 <code>.vue</code> 文件时会把 <code>&lt;T,&gt;</code> 规范化为 <code>&lt;T&gt;</code>，于是代码变成了：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 修复前（可正常解析）</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> buildList</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,&gt;(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 被 Prettier 2 改写后（被当成 JSX 标签，解析失败）</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> buildList</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list;</span></span></code></pre></div><p><strong>处理</strong>：升级 <code>@huangjunsen/encode-fe-lint</code> 到 <code>&gt;=1.0.14</code>（内置 Prettier 3.x，会保留 <code>&lt;T,&gt;</code>）。</p><hr><h2 id="_5-扫描时把第三方打包产物也算了进来" tabindex="-1">5. 扫描时把第三方打包产物也算了进来 <a class="header-anchor" href="#_5-扫描时把第三方打包产物也算了进来" aria-label="Permalink to &quot;5. 扫描时把第三方打包产物也算了进来&quot;">​</a></h2><p><strong>现象</strong>：报告中出现大量来自 <code>node_modules</code> 之外的压缩 / 打包文件的告警，例如 vendored 进源码目录的 UMD 产物。</p><p><strong>原因</strong>：这类文件是构建产物，不应对其做规范检查。</p><p><strong>处理</strong>：升级 <code>@huangjunsen/encode-fe-lint</code> 到 <code>&gt;=1.0.14</code>（默认忽略已包含 <code>**/*.umd.js</code>）。</p><p>对于其他约定俗成的产物路径（如 <code>**/vendor/**</code>），请在项目根目录的 <code>.eslintignore</code> 中自行补充。</p><hr><h2 id="_6-项目原有的-prettier-stylelint-配置疑似失效" tabindex="-1">6. 项目原有的 prettier / stylelint 配置疑似失效 <a class="header-anchor" href="#_6-项目原有的-prettier-stylelint-配置疑似失效" aria-label="Permalink to &quot;6. 项目原有的 prettier / stylelint 配置疑似失效&quot;">​</a></h2><p><code>prettier.config.js</code> 与 <code>stylelint.config.js</code> 的解析优先级<strong>低于</strong> <code>.prettierrc.js</code> 与 <code>.stylelintrc.js</code>。当项目同时存在两者时，后者的规则会生效。</p><p><code>encode-fe-lint init</code> 会把这两类同名文件列为「与工具冲突的配置」并在覆盖前给出提示（<code>&gt;=1.0.13</code>）。若你希望保留项目原有配置，请在初始化完成后删除工具生成的 <code>.prettierrc.js</code> / <code>.stylelintrc.js</code>。</p><hr><h2 id="_7-扫描耗时过长" tabindex="-1">7. 扫描耗时过长 <a class="header-anchor" href="#_7-扫描耗时过长" aria-label="Permalink to &quot;7. 扫描耗时过长&quot;">​</a></h2><p>排查顺序：</p><ol><li>确认 <code>node_modules</code>、<code>dist</code>、<code>build</code> 等产物目录已被忽略（检查 <code>.eslintignore</code> 与项目根目录的 ignore 配置）；</li><li>使用 <code>encode-fe-lint scan --include src</code> 缩小扫描范围；</li><li>若项目为 monorepo，留意子包目录下的 <code>node_modules</code> 是否被正确排除。</li></ol>',44)])])}const k=o(t,[["render",a]]);export{g as __pageData,k as default};
